210	     */
211	    public Integer getMembershipLevel() {
212	        int level = 1;
213	        if (this.email != null && !this.email.isBlank()) {
214	            level++;
215	        }
216	        if (this.namesakeCount != null && this.namesakeCount == 0) {
217	            level++;
218	        }
219	        return Math.min(level, 3);
