222	    /**
223	     * The Luhn check digit (0-9) computed over the digits contained in this owner's
224	     * {@code customerCode}. Non-digit characters are ignored; the rightmost digit is doubled.
225	     *
226	     * @return the single Luhn check digit, or {@code null} when there is no customer code
227	     */
228	    public Integer getCheckDigit() {
229	        if (this.customerCode == null) {
230	            return null;
231	        }
232	        int sum = 0;
233	        boolean dbl = true;
234	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
235	            char c = this.customerCode.charAt(i);
236	            if (c < '0' || c > '9') {
237	                continue;
238	            }
239	            int d = c - '0';
240	            if (dbl) {
241	                d *= 2;
242	                if (d > 9) {
243	                    d -= 9;
244	                }
245	            }
246	            sum += d;
247	            dbl = !dbl;
248	        }
