283	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
284	    }
285	
286	    /**
287	     * The owner's identity key: the single derived value used to detect duplicate owners. It is the
288	     * owner's normalized telephone, its email (empty when none) and its {@code householdId} (empty
289	     * when none) joined by {@code '|'}. Because the telephone is part of the key, two members of the
290	     * same household with different telephones have different identity keys; only owners whose whole
291	     * key is identical are duplicates.
292	     *
293	     * @return the {@code normalizedTelephone|email|householdId} identity key
294	     */
295	    public String getIdentityKey() {
296	        String telephonePart = this.telephone == null ? "" : this.telephone;
297	        String emailPart = this.email == null ? "" : this.email;
298	        String householdPart = this.householdId == null ? "" : this.householdId;
299	        return telephonePart + '|' + emailPart + '|' + householdPart;
300	    }
301	
302	    protected Set<Pet> getPetsInternal() {
303	        if (this.pets == null) {
304	            this.pets = new HashSet<>();
305	        }
306	        return this.pets;
307	    }
308	
309	    protected void setPetsInternal(Set<Pet> pets) {
310	        this.pets = pets;
311	    }
312	
313	    public List<Pet> getPets() {
314	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
315	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
316	        return Collections.unmodifiableList(sortedPets);
317	    }
318	
319	    public void setPets(List<Pet> pets) {
320	        this.pets = new HashSet<>(pets);
321	    }
322	
323	    public void addPet(Pet pet) {
324	        getPetsInternal().add(pet);
325	        pet.setOwner(this);
326	    }
