343	     */
344	    public Pet getPet(String name, boolean ignoreNew) {
345	        name = name.toLowerCase();
346	        for (Pet pet : getPetsInternal()) {
347	            if (!ignoreNew || !pet.isNew()) {
348	                String compName = pet.getName();
349	                compName = compName.toLowerCase();
350	                if (compName.equals(name)) {
351	                    return pet;
352	                }
353	            }
354	        }
355	        return null;
356	    }
